sp_widget.css:
.faq-widget {
  padding: 25px;
  margin: 30px auto;
  max-width: 800px;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  color: #003366;
}

.faq-widget h2 {
  font-size: 1.8rem;
  margin-bottom: 20px;
  color: #007799;
  text-align: center;
}

.faq-item {
  margin-bottom: 20px;
}

.faq-item h3 {
  font-size: 1.2rem;
  margin-bottom: 5px;
  color: #005577;
}

.faq-item p {
  font-size: 1rem;
  margin: 0;
}
